#include <memory>
#include <string>
#include <vector>

class Shape
{
public:
    virtual ~Shape() = default;
    virtual double area() const { return 0.0; }
    virtual std::string name() const { return "shape"; }
};

class Circle : public Shape
{
public:
    explicit Circle(double radius) : m_radius{ radius } {}
    double area() const override { return 3.14159 * m_radius * m_radius; }
    std::string name() const override { return "circle"; }

private:
    double m_radius{};
};

class Rectangle : public Shape
{
public:
    Rectangle(double width, double height) : m_width{ width }, m_height{ height } {}
    double area() const override { return m_width * m_height; }
    std::string name() const override { return "rectangle"; }

private:
    double m_width{};
    double m_height{};
};

class Triangle : public Shape
{
public:
    Triangle(double base, double height) : m_base{ base }, m_height{ height } {}
    double area() const override { return m_base * m_height / 2.0; }
    std::string name() const override { return "triangle"; }

private:
    double m_base{};
    double m_height{};
};

using Shapes = std::vector<std::unique_ptr<Shape>>;

double totalArea(const Shapes& shapes)
{
    double total{ 0.0 };
    for (const auto& shape : shapes)
    {
        total += shape->area();
    }
    return total;
}

std::string largestName(const Shapes& shapes)
{
    const Shape* best{ nullptr };
    for (const auto& shape : shapes)
    {
        if (best == nullptr || shape->area() > best->area())
        {
            best = shape.get();
        }
    }
    return best ? best->name() : "none";
}

unitTests:
Shapes sample() { Shapes s; s.push_back(std::make_unique<Circle>(1.0)); s.push_back(std::make_unique<Rectangle>(3.0, 4.0)); s.push_back(std::make_unique<Triangle>(4.0, 5.0)); return s; }
static_assert(std::has_virtual_destructor_v<Shape>);
TEST("each shape knows its own area and name") { const Circle c{ 2.0 }; const Shape& s{ c }; CHECK_NEAR(s.area(), 12.56636, 1e-5); CHECK_EQ(s.name(), "circle"); CHECK_NEAR(Rectangle(2, 5).area(), 10.0, 1e-9); CHECK_NEAR(Triangle(6, 3).area(), 9.0, 1e-9); }
TEST("totalArea") { CHECK_NEAR(totalArea(sample()), 3.14159 + 12.0 + 10.0, 1e-9); CHECK_NEAR(totalArea(Shapes{}), 0.0, 1e-12); }
TEST("largestName") { CHECK_EQ(largestName(sample()), "rectangle"); CHECK_EQ(largestName(Shapes{}), "none"); Shapes one; one.push_back(std::make_unique<Triangle>(1.0, 1.0)); CHECK_EQ(largestName(one), "triangle"); }

